"""Actual native append/reference receipts; no upstream mutable-array parity claim."""
import argparse, hashlib, json, pathlib, subprocess, tempfile, xml.etree.ElementTree as ET
p=argparse.ArgumentParser();p.add_argument('--executable',required=True,type=pathlib.Path);p.add_argument('--sdk-directory',required=True,type=pathlib.Path);p.add_argument('--directory',required=True,type=pathlib.Path);p.add_argument('--node',required=True);a=p.parse_args();out=a.directory.resolve();out.mkdir(parents=True,exist_ok=True);invocation=pathlib.Path(tempfile.mkdtemp(prefix='cases-',dir=out));groups=[]
def run(name,source,code=0):
 root=invocation/name;root.mkdir();suite=root/'suite.mjs';suite.write_text("import { defineNativeSuite } from "+json.dumps((a.sdk_directory/'native.js').resolve().as_uri())+";\nimport { strict as assert } from 'node:assert';\nconst root="+json.dumps(str(root))+";\n"+source)
 path=root/'actual.json';actual=subprocess.run([str(a.executable),'--node',a.node,'--host-script',str((a.sdk_directory/'native-runner-host.js').resolve()),'--suite',str(suite),'--report',str(path),'--junit',str(root/'actual.xml'),'--html',str(root/'actual.html')],capture_output=True,timeout=60);(root/'stdout.bin').write_bytes(actual.stdout);(root/'stderr.bin').write_bytes(actual.stderr);assert actual.returncode==code and not actual.stderr,(name,actual.returncode,actual.stdout,actual.stderr)
 value=json.loads(path.read_text());assert value['globalErrors']==[],(name,value);declarations=value.get('attachmentDeclarations',[]);files={x['id']:x for x in value['attachments']};owners={(x['testId'],x['generation'],x['workerIndex'],x['pid'])for x in value['attempts']}
 for row in declarations:
  assert(row['testId'],row['generation'],row['workerIndex'],row['pid'])in owners
  assert row['terminalMonotonicMs']>=row['declaredMonotonicMs']
  if row['receipt']=='committed':
   f=files[row['attachmentId']];assert f['writerExitConfirmed']and f['writerExitCode']==0 and f['writerPid']!=f['pid'] and f['writerExitReceiptMonotonicMs']==row['terminalMonotonicMs'];data=pathlib.Path(f['path']).read_bytes();assert len(data)==row['declaredByteLength']==f['byteLength'];f['_sha256']=hashlib.sha256(data).hexdigest();f['_data']=data
  else:assert'attachmentId'not in row
  if row['sourceKind']=='pathReference':assert not any(k in row for k in ['bytes','byteLength','path','writerPid','attachmentId','declaredByteLength'])
 xml=ET.parse(root/'actual.xml');props={v.attrib['name']:v.attrib.get('value','')for v in xml.findall('.//property')};value['_props']=props;value['_html']=(root/'actual.html').read_text();groups.append({'name':name,'report':str(path),'actualExitCode':actual.returncode,'declarations':len(declarations),'committedFiles':len(files)});return value
v=run('missing-authored-reference-absent-and-real-zero',r"""export default defineNativeSuite({tests:[{title:'declarations',run:(_,i)=>{assert.equal(i.attachments.push({name:'reference\ud800',contentType:'image/png',path:'missing\ud800/file.png'},{name:'',contentType:''},{name:'zero',contentType:'',body:Buffer.alloc(0)}),3);assert.equal(i.attachments.length,3);assert.equal(i.attachments[0].path,'missing\ud800/file.png');assert.equal('body' in i.attachments[1],false);assert.equal(i.attachments[2].body.length,0)}}]});""")
r=v['attachmentDeclarations'];assert[r0['receipt']for r0 in r]==['referenceAccepted','referenceAccepted','committed'];assert r[0]['declaredPath']=='missing\ud800/file.png'and'declaredByteLength'not in r[1]and r[2]['declaredByteLength']==0 and len(v['attachments'])==1 and v['attachments'][0]['_data']==b'';assert 'Author-declared path reference'in v['_html']
v=run('same-attempt-hook-body-view-and-normal-attach',r"""let view;export default defineNativeSuite({hooks:{beforeEach:[{run:(_,i)=>{view=i.attachments;view.push({name:'before',contentType:'x',path:'missing-before'})}}],afterEach:[{run:(_,i)=>{assert.equal(view,i.attachments);assert.deepEqual([...view].map(x=>x.name),['before','copied bytes','body']);i.attachments.push({name:'after',contentType:'x',path:'missing-after'})}}]},tests:[{title:'one attempt',run:async(_,i)=>{assert.equal(view,i.attachments);await i.attach('copied bytes',{body:'actual'});assert.equal(view[1].body.toString(),'actual');i.attachments.push({name:'body',contentType:'x',body:Buffer.from('actual body')})}}]});""")
assert[r['callbackKind']for r in v['attachmentDeclarations']]==['beforeEach','body','afterEach']and len(v['attachments'])==2 and v['summary']['expected']==1
v=run('snapshot-original-body-before-author-mutation',r"""export default defineNativeSuite({tests:[{title:'bytes',run:(_,i)=>{const body=Buffer.from([0,128,255]);i.attachments.push({name:'binary',contentType:'application/octet-stream',body});body.fill(19);i.attachments[0].body.fill(37)}}]});""")
assert v['attachments'][0]['_data']==bytes([0,128,255])
v=run('retry-and-worker-identity-isolation',r"""export default defineNativeSuite({tests:[{title:'retry',retries:1,run:(_,i)=>{assert.equal(i.attachments.length,0);i.attachments.push({name:'retry '+i.retry,contentType:'x',path:'uncreated '+i.retry});if(!i.retry)throw Error('actual first failure')}}]});""")
assert v['summary']['flaky']==1 and[r['name']for r in v['attachmentDeclarations']]==['retry 0','retry 1']and len({r['pid']for r in v['attachmentDeclarations']})==2 and not v['attachments']
v=run('stale-saved-view-and-invalid-batch-no-admission',r"""let stale;export default defineNativeSuite({tests:[{title:'old',run:(_,i)=>{stale=i.attachments}},{title:'current',run:(_,i)=>{assert.throws(()=>stale.push({name:'foreign',contentType:'x'}),/another actual attempt/);assert.throws(()=>i.attachments.push({name:'valid',contentType:'x'},{name:'invalid',contentType:'x',body:Buffer.from('x'),path:'x'.repeat(8193)}));assert.equal(i.attachments.length,0);assert.deepEqual(i.attachments.splice(0,0),[]);i.attachments.push({name:'only genuine declaration',contentType:'x'})}}]});""")
assert len(v['attachmentDeclarations'])==1 and v['attachmentDeclarations'][0]['testId']=='2'and not v['attachments']
failed=r"""for(let n=0;n<5;++n)i.attachments.push({name:'actual '+n,contentType:'application/octet-stream',body:Buffer.alloc(1024*1024,n)});"""
v=run('ignored-native-capacity-error-fails-callback',"export default defineNativeSuite({tests:[{title:'native failure',run:(_,i)=>{"+failed+"}}]});",1)
assert v['attempts'][0]['status']=='failed'and'capacity'in v['attempts'][0]['error']and any(r['receipt']=='failed'and'capacity'in r['error']for r in v['attachmentDeclarations'])and len(v['attachments'])==4
v=run('raw-boxed-author-error-primary-with-separate-native-append-error',"export default defineNativeSuite({tests:[{title:'raw primary',run:async(_,i)=>{await i.step('actual box',async()=>{"+failed+"throw Error('raw authored cause remains primary')},{box:true})}}]});",1)
assert'raw authored cause remains primary'in v['attempts'][0]['error']and v['attempts'][0].get('originatingStepId')and v['attempts'][0].get('errorAttribution')and any(r['receipt']=='failed'and'capacity'in r['error']for r in v['attachmentDeclarations'])
v=run('static-expected-failure-keeps-actual-native-append-failure',"export default defineNativeSuite({tests:[{title:'native expected failure',expectedFailure:true,run:(_,i)=>{"+failed+"}}]});")
assert v['attempts'][0]['status']=='failed'and v['attempts'][0]['expected']and any(r['receipt']=='failed'for r in v['attachmentDeclarations'])
v=run('accepted-test-skip-keeps-native-reference-and-file-cancellation',r"""export default defineNativeSuite({tests:[{title:'actual skip',run:(_,i)=>{i.attachments.push({name:'author ref',contentType:'x',path:'not-created'},{name:'pending native body',contentType:'x',body:Buffer.alloc(1024*1024,7)});i.skip('actual native skip cause')}}]});""")
assert v['attempts'][0]['status']=='skipped'and v['summary']['skipped']==1 and v['attachmentDeclarations'][0]['receipt']=='referenceAccepted'and v['attachmentDeclarations'][1]['receipt']=='canceled'and v['attachmentDeclarations'][1]['cancellationRequestId']
(out/'report.json').write_text(json.dumps({'passed':len(groups),'scope':'Actual native append/reference/context and callback/file receipts; no mutable-array or unchanged upstream direct-push parity claim','groups':groups},indent=2)+'\n');print('PASS',len(groups),'actual native attachment append process groups')
